195	/**
196	 * Updates an existing knowledge insight identified by its numeric ID.
197	 *
198	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
199	 * for non-integer, zero, or floating-point strings). Validates the request body
200	 * via `KnowledgeUpdateBodySchema` (throws VALIDATION_ERROR for unknown fields or
201	 * type mismatches). Extracts `scope` and `project_slug` discriminator fields to
202	 * scope the update to the correct store.
203	 *
204	 * `superseded_by: null` in the body is mapped to `undefined` so the field is
205	 * cleared (removed) on the stored insight.
206	 *
207	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
208	 *
209	 * @param ledgerRoot  Absolute path to the central ledger root.
210	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
211	 * @param body        Parsed request body (any shape — validated here).
212	 * @returns The updated Insight.
213	 */
214	export async function handleUpdateKnowledge(
215	  ledgerRoot: string,
216	  rawId: string,
217	  body: unknown
218	): Promise<Insight> {
219	  const id = parseKnowledgeId(rawId);
220	
221	  const parseResult = KnowledgeUpdateBodySchema.safeParse(body);
222	  if (!parseResult.success) {
223	    validationError('Invalid knowledge update body.', parseResult.error.issues);
224	  }
225	
226	  const { scope, project_slug, superseded_by, ...rest } = parseResult.data;
227	
228	  // Map superseded_by: null → undefined so the field is cleared on the stored insight.
229	  const updates: Parameters<KnowledgeStoreManager['updateInsight']>[1] = {
230	    ...rest,
231	    ...(superseded_by === null ? { superseded_by: undefined } : superseded_by !== undefined ? { superseded_by } : {}),
232	  };
233	
234	  const manager = new KnowledgeStoreManager(ledgerRoot);
235	
236	  try {
237	    return await manager.updateInsight(id, updates, { scope, project_slug });
238	  } catch (err) {
239	    const msg = err instanceof Error ? err.message : String(err);
240	    if (msg.includes('not found')) {
241	      throw new ApiError('NOT_FOUND', 'Insight not found.');
242	    }
243	    throw err;
244	  }
245	}
246	
247	// ---------------------------------------------------------------------------
248	// DELETE /api/knowledge/:id
249	// ---------------------------------------------------------------------------
250	
251	/**
252	 * Deletes an existing knowledge insight identified by its numeric ID.
253	 *
254	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
255	 * for non-integer, zero, or floating-point strings). Requires `scope` as a
256	 * query parameter; when `scope === 'project'`, `project_slug` is also required
257	 * (throws VALIDATION_ERROR if absent). Scopes the deletion to the correct store
258	 * to prevent accidental cross-scope deletion when the same numeric ID exists in
259	 * multiple stores.
260	 *
261	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
262	 *
263	 * @param ledgerRoot   Absolute path to the central ledger root.
264	 * @param rawId        Raw ID string from the URL parameter (e.g. "42").
265	 * @param scope        Required scope query parameter ('global' or 'project').
266	 * @param project_slug Required when scope is 'project'; the project slug.
267	 * @returns `null` — consistent with other delete handlers.
268	 */
269	export async function handleDeleteKnowledge(
270	  ledgerRoot: string,
271	  rawId: string,
272	  scope: string | undefined,
273	  project_slug?: string
274	): Promise<null> {
275	  const id = parseKnowledgeId(rawId);
276	
