306	// ---------------------------------------------------------------------------
307	
308	/**
309	 * Promotes a project-scoped insight to global scope using the atomic
310	 * KnowledgeStoreManager.moveInsight() method.
311	 *
312	 * The returned insight is the newly created global-scoped copy — it has a
313	 * **different numeric ID** than the original (assigned by the global store's
314	 * `next_id` counter). The frontend must match by pre-promote ID, not the new ID.
315	 *
316	 * @param ledgerRoot  Absolute path to the central ledger root.
317	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
318	 * @param scope       Source scope — must be "project" (global insights cannot be promoted).
319	 * @param project_slug Required when scope is "project"; the source project slug.
320	 * @returns The newly created global Insight.
321	 * @throws ApiError VALIDATION_ERROR if scope is not "project", or insight is already global.
322	 * @throws ApiError NOT_FOUND if no matching insight exists in the specified scope.
323	 */
324	export async function handlePromoteKnowledge(
325	  ledgerRoot: string,
326	  rawId: string,
327	  scope: string | undefined,
328	  project_slug?: string
329	): Promise<Insight> {
330	  const id = parseKnowledgeId(rawId);
331	
332	  // Validate scope — must be 'project' (global insights are already global).
333	  const scopeResult = InsightScope.safeParse(scope);
334	  if (!scopeResult.success) {
335	    validationError('scope query parameter is required and must be "global" or "project".');
336	  }
337	  const validatedScope = scopeResult.data;
338	
339	  if (validatedScope === 'global') {
340	    validationError('Insight is already global and cannot be promoted.');
341	  }
342	
343	  // project_slug is required when scope === 'project'.
344	  if (!project_slug) {
345	    validationError('project_slug query parameter is required when scope is "project".');
346	  }
347	
348	  const manager = new KnowledgeStoreManager(ledgerRoot);
349	
350	  try {
351	    return await manager.moveInsight(
352	      id,
353	      { scope: validatedScope, project_slug },
354	      'global'
355	    );
356	  } catch (err) {
357	    const msg = err instanceof Error ? err.message : String(err);
358	    if (msg.includes('not found') || msg.toLowerCase().includes('not found')) {
359	      throw new ApiError('NOT_FOUND', 'Insight not found.');
360	    }
361	    throw err;
362	  }
363	}
