367	// ---------------------------------------------------------------------------
368	
369	/**
370	 * Moves an insight from one scope/project to a different project using the
371	 * atomic KnowledgeStoreManager.moveInsight() method.
372	 *
373	 * Supports two move variants:
374	 * - global → project: promotes the global insight into a named project store
375	 * - project → project: moves a project insight to a different project
376	 *
377	 * The returned insight is the newly created copy — it has a **different numeric
378	 * ID** (assigned by the target store's `next_id` counter).
379	 *
380	 * @param ledgerRoot  Absolute path to the central ledger root.
381	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
382	 * @param body        Parsed request body (validated against KnowledgeMoveBodySchema).
383	 * @returns The newly created Insight in the target project store.
384	 * @throws ApiError VALIDATION_ERROR when source and destination are identical, body is invalid,
385	 *   or the destination slug fails PROJECT_SLUG_REGEX.
386	 * @throws ApiError NOT_FOUND when no matching insight exists in the source scope.
387	 */
388	export async function handleMoveKnowledge(
389	  ledgerRoot: string,
390	  rawId: string,
391	  body: unknown
392	): Promise<Insight> {
393	  const id = parseKnowledgeId(rawId);
394	
395	  const parseResult = KnowledgeMoveBodySchema.safeParse(body);
396	  if (!parseResult.success) {
397	    validationError('Invalid knowledge move body.', parseResult.error.issues);
398	  }
399	
400	  const { source_scope, source_project_slug, project_slug } = parseResult.data;
401	
402	  // Require source_project_slug when source_scope is 'project'.
403	  if (source_scope === 'project' && !source_project_slug) {
404	    validationError('source_project_slug is required when source_scope is "project".');
405	  }
406	
407	  // Validate that source and destination are not identical.
408	  // global → project always changes scope, so no identity check is needed for that case.
409	  if (source_scope === 'project' && source_project_slug === project_slug) {
410	    validationError('Source and destination project are identical; nothing to move.');
411	  }
412	
413	  const manager = new KnowledgeStoreManager(ledgerRoot);
414	
415	  try {
416	    return await manager.moveInsight(
417	      id,
418	      { scope: source_scope, project_slug: source_project_slug },
419	      'project',
420	      project_slug
421	    );
422	  } catch (err) {
423	    const msg = err instanceof Error ? err.message : String(err);
424	    if (msg.includes('not found') || msg.toLowerCase().includes('not found')) {
425	      throw new ApiError('NOT_FOUND', 'Insight not found.');
426	    }
427	    throw err;
428	  }
429	}

